calc.mjs.text:
// Pure Whatnot sale arithmetic. No network, no stored live schedule.
//
// Every rate is an input. The category presets below are illustrative
// starting points taken from Whatnot's published US help article (commission
// on the item price, processing on the checkout total) — a seller is
// expected to replace them with the numbers on their own payout statement.
// The result is a transparent calculation from those inputs, not Whatnot's
// live schedule and not advice about what to list or what to charge.
//
// The product exists because the headline "8%" (or the "about 6%" figure
// that drops processing) is not the number that decides whether a lot
// makes money. Commission is on the hammer. Processing is on what the
// buyer actually paid — item + shipping + tax — plus a flat 30 cents. A
// $20 card with $5 buyer-paid shipping looks like $1.60 in fees and is
// $3.025. The $1,500 cap on TCG / comics / sports / toys is the other
// half: a $2,400 graded lot is not 8% of $2,400.

export const CATEGORY_PRESETS = Object.freeze({
  standard: {
    id: 'standard',
    label: 'All other categories (US default)',
    short: '8%, no cap',
    note: 'Whatnot’s published US default for categories that are not on the limited-time cap list. Confirm on the lot.',
    commissionRate: 8,
    commissionCap: '',
  },
  tcg: {
    id: 'tcg',
    label: 'Comics, TCG, sports singles, toys & hobbies',
    short: '8% up to $1,500',
    note: 'Published limited-time US shape: 8% on the hammer up to $1,500, 0% on the portion above. Expires; confirm on the lot.',
    commissionRate: 8,
    commissionCap: 1500,
  },
  coins: {
    id: 'coins',
    label: 'Coins & money',
    short: '4% up to $1,500',
    note: 'Published limited-time US shape: 4% on the hammer up to $1,500, 0% on the portion above.',
    commissionRate: 4,
    commissionCap: 1500,
  },
  pallets: {
    id: 'pallets',
    label: 'Pallets (wholesale)',
    short: '4%, no cap',
    note: 'Published limited-time US wholesale/pallet rate. No $1,500 cap on this row.',
    commissionRate: 4,
    commissionCap: '',
  },
});

// Whatnot's published default processor rate. Exported rather than left as a
// bare literal in `calculateSale` below because `where-to-sell-calculator`'s
// Whatnot channel preset has to quote the same number — see that page's
// `channel-parity.test.mjs`, which imports these two constants directly so a
// change here fails there instead of the two tools silently disagreeing about
// what Whatnot charges.
export const DEFAULT_PAYMENT_RATE = 2.9;
export const DEFAULT_PAYMENT_FIXED = 0.3;

export const INPUT_IDS = Object.freeze([
  'salePrice',
  'shippingCharged',
  'taxCharged',
  'shippingCost',
  'itemCost',
  'otherCost',
  'commissionRate',
  'commissionCap',
  'paymentRate',
  'paymentFixed',
  'lotsPerShow',
  'targetLeftover',
]);

function isBlank(value) {
  return value === '' || value === null || value === undefined || String(value).trim() === '';
}

function number(value, name, { min = 0, allowBlank = false, blankValue = 0 } = {}) {
  if (isBlank(value)) {
    if (allowBlank) return blankValue;
    throw new Error(`${name} is required`);
  }
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  return result;
}

export function applyCategoryPreset(input, presetId) {
  const preset = CATEGORY_PRESETS[presetId];
  if (!preset) throw new Error(`Unknown category preset: ${presetId}`);
  return {
    ...input,
    commissionRate: preset.commissionRate,
    commissionCap: preset.commissionCap,
  };
}

function commissionOn(salePrice, commissionRate, commissionCap) {
  const taxable = commissionCap === null ? salePrice : Math.min(salePrice, commissionCap);
  return taxable * (commissionRate / 100);
}

/**
 * One Whatnot sale, priced the way a payout statement actually lands.
 *
 * @param {object} input
 * @param {number} input.salePrice          Hammer / BIN — Whatnot's commission base.
 * @param {number} [input.shippingCharged]  Shipping the buyer paid at checkout.
 * @param {number} [input.taxCharged]       Sales tax collected at checkout.
 * @param {number} [input.shippingCost]     What the outbound label actually costs you.
 * @param {number} [input.itemCost]         What the lot cost you.
 * @param {number} [input.otherCost]        Supplies, inserts, show props on this lot.
 * @param {number} input.commissionRate     Commission % of the hammer.
 * @param {number|string} [input.commissionCap] Hammer dollars above which commission is 0. Blank = no cap.
 * @param {number} [input.paymentRate]      Processing % of checkout total. Default 2.9.
 * @param {number} [input.paymentFixed]     Flat processing fee. Default 0.30.
 * @param {number} [input.lotsPerShow]      For the show roll-up. Default 1.
 * @param {number} [input.targetLeftover]   Desired leftover after fees and costs. Default 0.
 * @param {boolean} [input.giveaway]        Force commission to $0 (Whatnot's giveaway shape).
 */
export function calculateSale(input) {
  const errors = [];
  const read = (id, label, opts) => {
    try {
      return number(input[id], label, opts);
    } catch (error) {
      errors.push({ id, message: error.message });
      return 0;
    }
  };

  const salePrice = read('salePrice', 'Sale price');
  const shippingCharged = read('shippingCharged', 'Shipping charged', { allowBlank: true });
  const taxCharged = read('taxCharged', 'Tax charged', { allowBlank: true });
  const shippingCost = read('shippingCost', 'Shipping cost', { allowBlank: true });
  const itemCost = read('itemCost', 'What you paid for the lot', { allowBlank: true });
  const otherCost = read('otherCost', 'Other per-lot cost', { allowBlank: true });
  const commissionRate = read('commissionRate', 'Commission rate');
  const paymentRate = read('paymentRate', 'Payment processing rate', { allowBlank: true, blankValue: DEFAULT_PAYMENT_RATE });
  const paymentFixed = read('paymentFixed', 'Payment fixed fee', { allowBlank: true, blankValue: DEFAULT_PAYMENT_FIXED });
  const lotsPerShow = read('lotsPerShow', 'Lots in this show', { allowBlank: true, blankValue: 1, min: 0 });
  const targetLeftover = read('targetLeftover', 'Target leftover', { allowBlank: true });

  let commissionCap = null;
  if (!isBlank(input.commissionCap)) {
    try {
      commissionCap = number(input.commissionCap, 'Commission cap', { min: 0 });
    } catch (error) {
      errors.push({ id: 'commissionCap', message: error.message });
    }
  }

  if (commissionRate + paymentRate >= 100) {
    errors.push({
      id: 'commissionRate',
      message: 'Combined percentage fees must stay below 100%',
    });
  }

  if (errors.length) return { ok: false, errors };

  const giveaway = Boolean(input.giveaway);
  const commission = giveaway ? 0 : commissionOn(salePrice, commissionRate, commissionCap);
  const checkoutTotal = salePrice + shippingCharged + taxCharged;
  const processingPercent = checkoutTotal * (paymentRate / 100);
  const processing = processingPercent + paymentFixed;
  const fees = commission + processing;
  const payout = salePrice - fees;
  const leftover = payout + shippingCharged - shippingCost - itemCost - otherCost;
  const takeRateOnHammer = salePrice > 0 ? (fees / salePrice) * 100 : 0;
  const takeRateOnCheckout = checkoutTotal > 0 ? (fees / checkoutTotal) * 100 : 0;
  const processingOnShippingAndTax = (shippingCharged + taxCharged) * (paymentRate / 100);
  const commissionOnCappedPortion = commissionCap !== null && salePrice > commissionCap
    ? (salePrice - commissionCap) * (commissionRate / 100)
    : 0;

  const notes = [];
  if (giveaway) {
    notes.push('Giveaway: commission is $0. Processing still applies to whatever the buyer paid at checkout, and you still pay the label.');
  }
  if (processingOnShippingAndTax > 0) {
    notes.push(
      `Processing is on the checkout total, not just the hammer — $${processingOnShippingAndTax.toFixed(2)} of the processing fee is from buyer-paid shipping and tax.`,
    );
  }
  if (commissionOnCappedPortion > 0) {
    notes.push(
      `The $${(salePrice - commissionCap).toFixed(2)} above the $${commissionCap.toFixed(0)} cap is not commissioned — that is $${commissionOnCappedPortion.toFixed(2)} the headline ${commissionRate}% would have taken.`,
    );
  }
  if (shippingCharged === 0 && shippingCost > 0) {
    notes.push('Free shipping: the label comes out of leftover and processing is only on the hammer (plus any tax).');
  }
  if (leftover < 0) {
    notes.push('This lot loses money after fees, the label, and what you paid for it.');
  }

  return {
    ok: true,
    errors: [],
    salePrice,
    shippingCharged,
    taxCharged,
    shippingCost,
    itemCost,
    otherCost,
    commissionRate,
    commissionCap,
    paymentRate,
    paymentFixed,
    lotsPerShow,
    targetLeftover,
    giveaway,
    checkoutTotal,
    commission,
    processingPercent,
    processing,
    fees,
    payout,
    leftover,
    takeRateOnHammer,
    takeRateOnCheckout,
    processingOnShippingAndTax,
    commissionOnCappedPortion,
    showLeftover: leftover * lotsPerShow,
    hammerForTarget: hammerForTarget({
      targetLeftover,
      shippingCharged,
      taxCharged,
      shippingCost,
      itemCost,
      otherCost,
      commissionRate: giveaway ? 0 : commissionRate,
      commissionCap,
      paymentRate,
      paymentFixed,
    }),
    notes,
  };
}

/**
 * The hammer that produces exactly `targetLeftover` after the same fees and
 * costs. Shipping charged, tax, and the label stay as typed — only the
 * hammer moves. Returns null when the percentage fees leave no solvable
 * remainder.
 */
export function hammerForTarget({
  targetLeftover,
  shippingCharged,
  taxCharged,
  shippingCost,
  itemCost,
  otherCost,
  commissionRate,
  commissionCap,
  paymentRate,
  paymentFixed,
}) {
  const fixedCosts = paymentFixed - shippingCharged + shippingCost + itemCost + otherCost
    + (shippingCharged + taxCharged) * (paymentRate / 100);
  const needed = targetLeftover + fixedCosts;

  const uncappedShare = 1 - commissionRate / 100 - paymentRate / 100;
  if (uncappedShare <= 0) return null;
  const uncapped = needed / uncappedShare;
  if (commissionCap === null || uncapped <= commissionCap) return uncapped;

  const cappedShare = 1 - paymentRate / 100;
  if (cappedShare <= 0) return null;
  const cappedFixed = needed + commissionCap * (commissionRate / 100);
  return cappedFixed / cappedShare;
}

/**
 * The same lot with buyer-paid shipping zeroed, so a seller can see whether
 * eating the label is cheaper than paying processing on the postage.
 */
export function compareFreeShipping(input) {
  const charged = calculateSale(input);
  const free = calculateSale({ ...input, shippingCharged: 0 });
  return {
    charged,
    free,
    leftoverDelta: free.ok && charged.ok ? free.leftover - charged.leftover : null,
  };
}

share.mjs.text:
// A seller re-enters the same category preset, rates, and lot numbers on
// every single sale — the exact retyping this venture's own kill criteria
// asks whether they will put up with twice in 90 days. This module keeps the
// whole form: restored in the visitor's own browser between visits, and
// carried into a link they can send themselves or a co-seller.
//
// Nothing here is transmitted. `localStorage` is the visitor's own disk, and
// the link is only ever built in their browser and copied by them. The lot
// travels in the URL *fragment* (`#...`), never the query string: a fragment
// is not sent in the request line a server logs, nor in a `Referer` header a
// later click would carry, so a shared lot stays off the machines it passes
// through on the way to the recipient.
//
// The numeric field list is imported from `calc.mjs` rather than restated
// here, so a field added to the arithmetic is shareable and restorable the
// moment it exists — the drift `page.test.mjs` guards against on every other
// calculator in this fleet.

import { INPUT_IDS, CATEGORY_PRESETS } from './calc.mjs';

const FLAG_FIELDS = Object.freeze(['giveaway']);
const CHOICE_FIELDS = Object.freeze({ categoryPreset: Object.keys(CATEGORY_PRESETS) });

export function encodeInputs(input) {
  const params = new URLSearchParams();
  for (const field of INPUT_IDS) {
    // Blank uses the calculator's own fallback (commissionCap blank = no cap);
    // an explicit zero does not, so the two must stay distinguishable.
    if (input?.[field] === '') {
      params.set(field, '');
      continue;
    }
    const value = Number(input?.[field]);
    if (Number.isFinite(value) && value >= 0) params.set(field, String(value));
  }
  for (const field of FLAG_FIELDS) {
    if (input?.[field] === undefined) continue;
    // Encoded even when false — a sender who unticked "giveaway" sends a link
    // that must not re-tick it for the recipient.
    params.set(field, input[field] ? '1' : '0');
  }
  for (const [field, allowed] of Object.entries(CHOICE_FIELDS)) {
    const value = input?.[field];
    if (typeof value === 'string' && allowed.includes(value)) params.set(field, value);
  }
  return params.toString();
}

export function decodeInputs(value) {
  const params = new URLSearchParams(String(value || '').replace(/^[?#]/, ''));
  const result = {};
  for (const field of INPUT_IDS) {
    if (!params.has(field)) continue;
    if (params.get(field) === '') {
      result[field] = '';
      continue;
    }
    const number = Number(params.get(field));
    if (Number.isFinite(number) && number >= 0) result[field] = number;
  }
  for (const field of FLAG_FIELDS) {
    if (!params.has(field)) continue;
    result[field] = params.get(field) === '1';
  }
  // A crafted link cannot select a preset id the page does not offer — only
  // one of the four rows `calc.mjs` actually knows the rates for survives.
  for (const [field, allowed] of Object.entries(CHOICE_FIELDS)) {
    if (!params.has(field)) continue;
    const raw = params.get(field);
    if (allowed.includes(raw)) result[field] = raw;
  }
  return result;
}

// The supported way to apply a decoded link's numeric fields: every one the
// form owns gets written, so a field the sender left blank is cleared rather
// than left showing whatever the *recipient's own saved draft* put there.
// Applying a decoded link with a plain object spread (`{ ...saved,
// ...fromLink }`) looks like the link wins and is not — a key fromLink
// omits still falls through to saved's value for that key. See
// platform/ci/check_shared_link_clears.py.
//
// Deliberately scoped to INPUT_IDS, not FLAG_FIELDS/CHOICE_FIELDS: giveaway
// and categoryPreset are always encoded when a link is built at all (a
// checkbox and a <select> have no "blank" state), so they cannot carry the
// omitted-field defect this function exists to close — the page applies
// them from the decoded link directly, when present.
export function formValues(decoded) {
  return Object.fromEntries(INPUT_IDS.map(id => [id, decoded?.[id] !== undefined ? String(decoded[id]) : '']));
}

to-where-to-sell.mjs.text:
// Carries this lot's numbers into the where-to-sell calculator, with Whatnot
// already switched on, so comparing this item against eBay, Etsy, Amazon,
// Reverb and an own store does not mean retyping price, shipping and cost.
//
// This is the reverse of ../where-to-sell-calculator/handoff.mjs, which
// carries a comparison *into* this page. Before this module existed the link
// ran only one way: the where-to-sell calculator could hand its numbers down
// into this page, but a seller who landed here first (from a search for
// "Whatnot seller payout calculator", say) and then wanted to check the same
// item on eBay or Etsy had to retype everything. That is the exact failure
// where-to-sell-calculator's own VENTURE.yaml names as its first untested
// hypothesis: the handoff, not the depth of the second tool, decides whether
// the deeper scenarios ever get opened.
//
// Only the numbers every channel shares travel: sale price, shipping
// charged, shipping cost, item cost, and the other-cost bucket. Whatnot's own
// rates (commission, cap, processing) have no matching field on the
// where-to-sell side — it prices Whatnot from its own illustrative preset
// rather than asking for a rate schedule — so they are left out rather than
// guessed at, the same rule handoff.mjs itself follows for a field a target
// has no home for. Tax charged also has no home on the receiving side and is
// dropped for the same reason.
//
// The wire format is where-to-sell-calculator's own `#c=` shared-link
// payload (see its share.mjs: `decodeComparison`), not this page's own share
// format. `to-where-to-sell.test.mjs` imports that decoder directly so a
// change to its shape fails a test here instead of arriving as a silently
// wrong number there.

const SHARED_FIELDS = ['salePrice', 'shippingCharged', 'shippingCost', 'itemCost', 'otherCost'];
const TARGET_NAME = { salePrice: 'price' };

function cleanNumber(value) {
  // `Number('')` and `Number(null)` are both 0, so coercing first would turn
  // an untouched field into an explicit zero on arrival -- the silent-wrong-
  // number case this module exists to avoid.
  if (value === null || value === undefined) return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

/** The `#c=` payload for where-to-sell-calculator's own decoder. */
export function whereToSellPayload(input = {}) {
  const shared = {};
  for (const field of SHARED_FIELDS) {
    const value = cleanNumber(input[field]);
    if (value !== null) shared[TARGET_NAME[field] ?? field] = value;
  }
  // No per-channel rate values: Whatnot's own preset already carries the
  // illustrative commission and processing rates on the receiving side, and
  // nothing here maps cleanly onto its generic commissionRate/paymentRate
  // shape without guessing. Enabling the channel with no rate override is
  // exactly what a fresh visit that turns Whatnot on already does.
  return { shared, channels: [{ id: 'whatnot', enabled: true, values: {} }] };
}

/** A relative link into where-to-sell-calculator, carrying this item. */
export function whereToSellUrl(input = {}) {
  const payload = whereToSellPayload(input);
  const encoded = encodeURIComponent(JSON.stringify(payload));
  return `../where-to-sell-calculator/#c=${encoded}`;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores a
// hammer, a cost, a rate, or a leftover — a seller's lot economics are
// exactly the sort of thing that must not be transmitted anywhere.

const STORAGE_KEY = 'whatnot-seller-payout-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'sale_calculated') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
